import fitz
import re

def redact_text_on_page(page, search_text, case_sensitive=True):
    """Find and redact all instances of search_text on a page."""
    flags = 0 if case_sensitive else re.IGNORECASE
    areas = page.search_for(search_text)
    for area in areas:
        page.add_redact_annot(area, fill=(0, 0, 0))
    return len(areas)

def redact_rect(page, rect):
    """Redact a specific rectangular area."""
    page.add_redact_annot(rect, fill=(0, 0, 0))

def find_and_redact_by_pattern(page, pattern):
    """Search text blocks for a regex pattern and redact matching spans."""
    count = 0
    blocks = page.get_text("dict")["blocks"]
    for b in blocks:
        if "lines" in b:
            for line in b["lines"]:
                for span in line["spans"]:
                    if re.search(pattern, span["text"]):
                        page.add_redact_annot(fitz.Rect(span["bbox"]), fill=(0, 0, 0))
                        count += 1
    return count

